declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use App\Core\Database;use App\Services\LiveDisplaySessionService;$pdo=Database::connection();$token=trim((string)($_GET['token']??''));$s=LiveDisplaySessionService::byToken($pdo,$token);if(!$s||!$s['auto_page']||!in_array($s['screen_type'],['competitors','callbacks','finalists'],true)){http_response_code(204);exit;}$stateUrl=url('live-display/state.php?token='.rawurlencode($token));$test=$s['data_mode']==='test';$entryTable=$test?'bdc_test_scoring_entries':'bdc_scoring_entries';$count=0;$q=$pdo->prepare("SELECT COUNT(*) FROM {$entryTable} WHERE round_id=:r AND entry_status='active'");$q->execute(['r'=>$s['current_round_id']]);$count=(int)$q->fetchColumn();$settings=\App\Services\ProjectionSettingsService::get($pdo,(int)$s['current_round_id'],$test);$layout=\App\Services\ProjectionLayoutService::resolve((string)$settings['screen_format'],max(1,$count),(string)$settings['density'],$settings['custom_width']?:null,$settings['custom_height']?:null);$pages=max(1,(int)$layout['pages']);$next=((int)$s['page_number']%$pages)+1;$pdo->prepare("UPDATE bdc_live_display_sessions SET page_number=:p,state_version=state_version+1,updated_at=NOW() WHERE id=:id")->execute(['p'=>$next,'id'=>$s['id']]);http_response_code(204);